/**
 * Graphic elements (arrows, shapes, badges, speech bubbles, frames, bars, lines, symbols, and the holiday and party elements of
 * the content packs): original artwork generated by
 * formula in this build. Thumbnails are the element's own SVG shown as an image; adding one asks the server to make the
 * PNG and place it, through the same route an agent uses. Category names come from core (ELEMENT_CATEGORY_NAMES), so a new
 * category is named where it is defined.
 */
import { useMemo, useState } from 'react';
import { ELEMENTS, ELEMENT_CATEGORIES, ELEMENT_CATEGORY_NAMES, elementSvg, type ElementCategory } from '@pulseframe/core';
import { api, ApiFailure } from '../api.ts';
import { useEditorState } from './store.ts';
import './elementsBrowser.css';

const STR = {
  he: {
    title: 'אלמנטים גרפיים', search: 'חיפוש אלמנט', searchPlaceholder: 'חיפוש…', all: 'הכול', color: 'צבע', color2: 'צבע שני', list: 'אלמנטים', empty: 'אין תוצאות', add: 'הוספה במיקום הסמן', adding: 'מוסיף…', added: 'נוסף לציר הזמן',
    note: 'האלמנטים מצוירים בנוסחה בתוכנה הזאת, בלי תוכן של צד שלישי. אחרי ההוספה זה קליפ תמונה רגיל: אפשר להזיז, להגדיל, לסובב ולהנפיש.',
  },
  en: {
    title: 'Graphic elements', search: 'Search elements', searchPlaceholder: 'Search…', all: 'All', color: 'Colour', color2: 'Second colour', list: 'Elements', empty: 'No results', add: 'Add at the playhead', adding: 'Adding…', added: 'Added to the timeline',
    note: 'The elements are drawn by formula in this program, with no third-party content. Once added it is an ordinary picture clip: move, resize, rotate and animate it.',
  },
} as const;

export function ElementsBrowser() {
  const { editor, state } = useEditorState();
  const S = STR[state.lang];
  const [q, setQ] = useState('');
  const [cat, setCat] = useState<ElementCategory | 'all'>('all');
  const [color, setColor] = useState('#FFFFFF');
  const [color2, setColor2] = useState('#3DE0C8');
  const [adding, setAdding] = useState<string | null>(null);
  const [status, setStatus] = useState<{ kind: 'ok' | 'err'; text: string } | null>(null);
  const projectId = state.doc?.id;
  const shown = useMemo(() => {
    const n = q.trim().toLowerCase();
    return ELEMENTS.filter((e) => (cat === 'all' || e.category === cat) && (!n || e.name.he.toLowerCase().includes(n) || e.name.en.toLowerCase().includes(n)));
  }, [q, cat]);
  const thumbs = useMemo(() => new Map(shown.map((e) => [e.id, `data:image/svg+xml;charset=utf-8,${encodeURIComponent(elementSvg(e.id, { color, color2 }))}`])), [shown, color, color2]);
  if (!projectId) return null;
  const add = async (id: string, name: string) => {
    setAdding(id); setStatus(null);
    try {
      await api.addElement(projectId, { elementId: id, color, color2, start: editor.playhead });
      setStatus({ kind: 'ok', text: `${S.added}: ${name}` });
    } catch (e) {
      setStatus({ kind: 'err', text: e instanceof ApiFailure ? `${e.message}${e.hint ? ` ${e.hint}` : ''}` : e instanceof Error ? e.message : String(e) });
    } finally { setAdding(null); }
  };
  return (
    <section className="elements" data-testid="elements-browser" aria-labelledby="elements-title">
      <h2 id="elements-title">{S.title} <span className="muted" data-testid="elements-count">{ELEMENTS.length}</span></h2>
      <input type="search" dir="auto" value={q} onChange={(e) => setQ(e.target.value)} placeholder={S.searchPlaceholder} aria-label={S.search} data-testid="elements-search" />
      <div className="el-chips" role="group" aria-label={S.list}>
        <button type="button" aria-pressed={cat === 'all'} onClick={() => setCat('all')} data-testid="elements-cat-all">{S.all}</button>
        {ELEMENT_CATEGORIES.map((c) => <button key={c} type="button" aria-pressed={cat === c} onClick={() => setCat(c)} data-testid={`elements-cat-${c}`}>{ELEMENT_CATEGORY_NAMES[c][state.lang]}</button>)}
      </div>
      <div className="el-colors">
        <label>{S.color} <input type="color" value={color} onChange={(e) => setColor(e.target.value.toUpperCase())} data-testid="elements-color" /></label>
        <label>{S.color2} <input type="color" value={color2} onChange={(e) => setColor2(e.target.value.toUpperCase())} data-testid="elements-color2" /></label>
      </div>
      <ul className="el-grid" role="list" aria-label={S.list}>
        {shown.map((e) => {
          const name = e.name[state.lang];
          return (
            <li key={e.id} role="listitem">
              <button type="button" className="el-tile" data-testid="element-tile" data-id={e.id} disabled={adding !== null} aria-busy={adding === e.id} aria-label={`${S.add}: ${name}`} title={name} onClick={() => void add(e.id, name)}>
                <img src={thumbs.get(e.id)} alt="" width={56} height={56} loading="lazy" decoding="async" />
              </button>
            </li>
          );
        })}
      </ul>
      {shown.length === 0 && <p className="muted">{S.empty}</p>}
      <p className={`muted${status?.kind === 'err' ? ' danger' : ''}`} role="status" data-testid="elements-status">{adding ? S.adding : status?.text ?? ''}</p>
      <p className="muted">{S.note}</p>
    </section>
  );
}
